    def flatten(self, carrier) -> tuple[Float[Array, "N_e N_x"], "CarrierMeta"]:
        """Project carrier to a (N_e, N_x) array and a static metadata record."""
        ...

    @abc.abstractmethod
    def unflatten(
        self, particles: Float[Array, "N_e N_x"], meta: "CarrierMeta"
    ) -> Any:
